M = [
{"id":"bedelhac","yol":["Hac","Hac"],"baslik":"Başkası adına hac (bedel)","ar":"الحج عن الغير",
 "hanefi":"Haccı farz olduğu hâlde ölüm hastalığı, ağır ve sürekli bir engel gibi sebeplerle bizzat gidemeyen kişi yerine başkasını gönderebilir (bedel). Engel ölünceye kadar sürmelidir; sonradan iyileşirse kendisi yeniden haccetmelidir. Bedelin daha önce kendi haccını yapmış olması efdaldir; yapmamış olanı göndermek mekruh olmakla birlikte geçerlidir. Masraflar gönderenin malından karşılanır.",
 "mez":{"maliki":["Hayatta iken bedel sahih değil","Mâlikîlere göre hayatta olan kişi için bedel hac geçerli değildir; ölen kişi vasiyet etmişse malının üçte birinden yaptırılır."],
        "safii":["Caiz","Bedelin önce kendi haccını yapmış olması şarttır; yapmamışsa hac kendisine sayılır."],
        "hanbeli":["Caiz","Şâfiîler gibi bedelin önce kendi farz haccını yapmış olması şarttır."]},
 "sebep":"Haccın bedenî bir ibadet mi, yoksa mal ile beden karışık bir ibadet mi olduğu; Hasʿamlı kadın hadisinin genelliği.",
 "delil":[["hadis","Has‘amlı kadının babası adına haccı",hadis("أفأحج عنه قال نعم"),"Buhârî, Hac, 1; Müslim, Hac, 407: “Babam haccı yetişmiş ama binek üzerinde duramıyor, onun yerine haccedeyim mi?” “Evet.”"],
          ["hadis","Şübrüme hadisi",hadis("حج عن نفسك ثم حج عن شبرمة"),"Ebû Dâvûd, Menâsik, 25: “Önce kendin için haccet, sonra Şübrüme için.”"]],
 "usul":"Hanefîlere göre hac mal ve beden karışık bir ibadettir; beden yönünden acizlik doğunca malî yönüyle naip vasıtasıyla eda edilebilir."},
{"id":"zekatakraba","yol":["Zekât","Zekât ve fıtır"],"baslik":"Zekâtın akrabaya verilmesi","ar":"دفع الزكاة إلى الأقارب",
 "hanefi":"Zekât; kişinin usûlüne (anne, baba, dede, nine) ve fürûuna (çocuk, torun) ve eşine verilmez; çünkü bunların nafakası zaten ona aittir ya da aralarında menfaat ortaklığı vardır. Kardeş, amca, dayı, hala, teyze ve bunların çocukları muhtaç iseler zekât verilebilir; hatta hem zekât hem sıla-i rahim sevabı olduğu için efdaldir.",
 "mez":{"maliki":["Benzer","Nafakası kendisine ait olanlara verilmez; diğer muhtaç akrabaya verilebilir ve efdaldir."],
        "safii":["Benzer","Nafakası üzerine vacip olanlara verilmez; nafakası vacip olmayan akrabaya verilmesi efdaldir."],
        "hanbeli":["Benzer","Usûl ve fürûa verilmez; mirasçısı olduğu akrabaya verilip verilmeyeceğinde iki rivayet vardır."]},
 "sebep":"Zekâtın kişinin kendi menfaatine dönmemesi gerektiği ilkesi ve nafaka yükümlülüğünün kapsamı.",
 "delil":[["hadis","“Akrabaya sadaka hem sadaka hem sıla-i rahimdir.”",hadis("الصدقة على المسكين صدقة وعلى ذي الرحم ثنتان صدقة وصلة"),"Tirmizî, Zekât, 26; Nesâî, Zekât, 82."],
          ["ayet","Tevbe 9:60","./#9-60","Zekâtın verileceği sekiz sınıf."]],
 "usul":"Mülkiyetin tam olarak fakire geçmesi (temlîk) zekâtın rüknüdür; menfaati verene dönen yakınlara verilen zekâtta temlîk tam gerçekleşmiş sayılmaz."},
{"id":"kurbanvekalet","yol":["Kurban ve av","Kurban"],"baslik":"Kurbanı vekâletle kestirmek","ar":"التوكيل في الأضحية",
 "hanefi":"Kurbanını bizzat kesmesi efdal olmakla birlikte, başkasını vekil ederek kestirmek caizdir. Vekil, kurban sahibinin adına keser; kesim vakti kurbanın kesildiği yere göre belirlenir. Kurum ve derneklere vekâlet vermek de caizdir; kurbanın vaktinde kesildiğinden emin olunmalıdır.",
 "mez":{"maliki":["Caiz","Kendisi kesmesi efdaldir; Müslüman bir vekil keser."],
        "safii":["Caiz","Kesen vekilin Müslüman olması efdaldir; Ehl-i kitap vekil de kesebilir (mekruh)."],
        "hanbeli":["Caiz","Kurban sahibinin kesime şahit olması müstehaptır."]},
 "sebep":"Mala bağlı ibadetlerde vekâletin caiz olduğu genel ilkesi; ittifak hâli.",
 "delil":[["hadis","Hz. Peygamber’in kurbanlarının bir kısmını Hz. Ali’ye kestirmesi",hadis("فنحر ثلاثا وستين بيده ثم أعطى عليا فنحر ما غبر"),"Müslim, Hac, 147."]],
 "usul":"Malî ibadetlerde niyabet (vekâlet) caizdir; kurban mal ile yapılan bir ibadet olduğundan vekâlete elverişlidir."},
{"id":"orucigne","yol":["Oruç","Oruç"],"baslik":"Oruçluyken iğne ve serum","ar":"الإبرة للصائم",
 "hanefi":"Klasik Hanefî ölçüsü, bir maddenin vücuttaki doğal ya da açık bir yoldan (menfez) mideye veya beyne ulaşmasıdır. Buna göre deri, kas veya damar yoluyla yapılan tedavi amaçlı iğneler orucu bozmaz. Diyanet İşleri Başkanlığı Din İşleri Yüksek Kurulu’na göre de tedavi amaçlı iğne orucu bozmaz; ancak gıda veya güç verme amacıyla yapılan serum ve besleyici iğneler, oruçtan beklenen açlığı ortadan kaldırdığı için orucu bozar ve kazası gerekir.",
 "mez":{"maliki":["Günümüz âlimlerinin çoğu: bozmaz","Besleyici olmayan iğne bozmaz; besleyici serum bozar görüşü yaygındır."],
        "safii":["Günümüz âlimlerinin çoğu: bozmaz","Damar yoluyla besleyici serum konusunda görüş ayrılığı vardır."],
        "hanbeli":["Günümüz âlimlerinin çoğu: bozmaz","Besleyici serumun bozduğu görüşü ağırlıktadır."]},
 "sebep":"Klasik eserlerde iğne bulunmadığı için hükmün, “cevfe (iç boşluğa) ulaşma” ve “gıda yerine geçme” ölçülerinden hangisine göre kurulacağı.",
 "delil":[["ayet","Bakara 2:187","./#2-187","“…Sonra orucu gece girinceye kadar tamamlayın.”"],
          ["hadis","“Oruç, girenden dolayıdır; çıkandan dolayı değil.”",hadis("الفطر مما دخل وليس مما خرج"),"İbn Abbâs’tan mevkûf olarak Buhârî ta‘lîken nakleder (Savm, 32)."]],
 "usul":"Yeni meselelerde hüküm, klasik fıkıhtaki illetlerin (menfez ve gıda olma) yeni duruma tatbikiyle (tahrîcü’l-menât ve tahkîku’l-menât) belirlenir."},
{"id":"sahuriftar","yol":["Oruç","Oruç"],"baslik":"Sahuru geciktirmek, iftarda acele etmek","ar":"تأخير السحور وتعجيل الفطر",
 "hanefi":"Sahura kalkmak ve sahuru imsak vaktinin yakınına kadar geciktirmek, iftarı da güneşin battığı kesinleşince hemen yapmak sünnettir. Tan yerinin ağardığından şüphe edilen vakitte yemek mekruhtur; güneşin battığından şüphe edilirken iftar etmek caiz değildir. İftarı hurma veya suyla açmak müstehaptır.",
 "mez":{"maliki":["Sünnet","Dört mezhep bu konuda ittifak hâlindedir."],
        "safii":["Sünnet","Hurma, yoksa su ile iftar etmek sünnettir."],
        "hanbeli":["Sünnet","İftarda acele etmek, sahuru geciktirmek sünnettir."]},
 "sebep":"İttifak bulunan bir meseledir; ayrılık yalnız şüpheli vakitlerin hükmündedir.",
 "delil":[["hadis","“İnsanlar iftarda acele ettikçe hayır üzeredir.”",hadis("لا يزال الناس بخير ما عجلوا الفطر"),"Buhârî, Savm, 45; Müslim, Sıyâm, 48."],
          ["hadis","“Sahur yapın; sahurda bereket vardır.”",hadis("تسحروا فإن في السحور بركة"),"Buhârî, Savm, 20; Müslim, Sıyâm, 45."]],
 "usul":"Asıl olan, vaktin devam ettiğidir (istishâb): şüphe anında sahurda gecenin, iftarda gündüzün devam ettiği kabul edilir."},
]
